import {licenseSample,licenseChecks,licenseAgents,advanceLicenseSample} from './digital-order-model.mjs';

const root=document.querySelector('#digital-order-app');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=licenseSample(),error='';
const actionLabels={paid:'Review sample evidence',reviewed:'Preview one assignment',previewed:'Approve sample preview',approved:'Apply sample assignment',applied:'Check sample activation',held:'Evidence on hold',unverified:'Verification incomplete',verified:'Restart sample'};
const nextAction=s=>actionLabels[s.phase]||'Restart sample';
const steps=[['01','Purchase','Match the exact order'],['02','Investigation','Read four perspectives'],['03','Decision','Preview and approve'],['04','Proof','Check assignment and activation']];
const stage=s=>s.phase==='paid'?0:['reviewed','held'].includes(s.phase)?1:['previewed','approved'].includes(s.phase)?2:3;

function render(){
 const s=state,checks=licenseChecks(s),agents=s.review?.agents||[],current=stage(s),complete=s.phase==='verified';
 root.innerHTML=`<div class="workspace"><a class="back" href="focus.html">← Merchant workspace</a><div class="hero"><div><span class="eyebrow">DIGITAL ORDERS · SOFTWARE LICENSE</span><h1>Paid. No license. One clear path back.</h1><p>Morgan bought a software license, but the assignment never appeared. Follow the same evidence-first recovery pattern used for course access.</p></div><div class="sample-tag"><strong>Fictional sample</strong><span>No PayPal, license-provider, AI-model, or customer-service calls</span></div></div><div class="steps" aria-label="Sample recovery progress">${steps.map(([number,label,description],index)=>`<div class="step ${index===current?'active':index<current?'done':''}" ${index===current?'aria-current="step"':''}><span>${number}</span><div><strong>${label}</strong><small>${description}</small></div></div>`).join('')}</div><div class="layout"><div class="case-main"><section class="order-card" aria-labelledby="order-title"><div class="section-head"><div><span class="eyebrow">PURCHASED ITEM</span><h2 id="order-title">${esc(s.order.product)}</h2></div><span class="status ${complete?'verified':''}">${complete?'Sample verified':s.phase==='held'?'Evidence hold':s.phase==='applied'?'Needs verification':'Access missing'}</span></div><div class="order-facts"><div><span>Order</span><strong>${esc(s.order.id)}</strong></div><div><span>Buyer account</span><strong>${esc(s.order.account)}</strong></div><div><span>License SKU</span><strong>${esc(s.order.sku)}</strong></div><div><span>Payment</span><strong>$${(s.order.amount/100).toFixed(2)} ${esc(s.order.currency)} · sample</strong></div></div></section><section class="evidence-card" aria-labelledby="evidence-title"><div class="section-head"><div><span class="eyebrow">THE EVIDENCE</span><h2 id="evidence-title">${complete?'Payment, assignment, and activation agree.':s.writes?'Payment and assignment agree. Activation is next.':'Payment is confirmed. Delivery is not.'}</h2></div><span class="fact-count">${checks.slice(0,5).filter(item=>item.ok).length}/5 purchase fields match</span></div><div class="signal"><div class="signal-item good"><span>01 Payment</span><strong>${s.payment.status==='COMPLETED'?'Recorded':'Unconfirmed'}</strong><small>Fictional capture and saved order</small></div><div class="signal-item ${s.delivery.assignment==='active'?'good':'warn'}"><span>02 Assignment</span><strong>${s.delivery.assignment==='active'?'Active':'Missing'}</strong><small>License service sample record</small></div><div class="signal-item ${s.proof?.activation?'good':''}"><span>03 Activation</span><strong>${s.proof?.activation?'Checked':'Not verified'}</strong><small>Separate buyer-access check</small></div></div><details class="checks"><summary>Inspect the exact purchase checks</summary><ul>${checks.map(item=>`<li><span aria-hidden="true">${item.ok?'✓':'·'}</span>${esc(item.label)}<strong>${item.ok?'Matches':'Needs review'}</strong></li>`).join('')}</ul><p>These are fictional records. A connected license provider would require fresh reads of the actual assignment and activation state.</p></details></section>${s.review?`<section class="agents" aria-labelledby="agents-title"><div class="section-head"><div><span class="eyebrow">SCRIPTED SPECIALIST REVIEW</span><h2 id="agents-title">Four views. One bounded decision.</h2></div><span class="status">${s.review.outcome==='ready'?'Ready for preview':'On hold'}</span></div><p class="section-intro">Confidence describes evidence support in this fictional snapshot. It is not a model probability or an authorization.</p><div class="agent-grid">${agents.map(agent=>`<article><div class="agent-head"><strong>${esc(agent.name)}</strong><span>${esc(agent.role)}</span></div><p>${esc(agent.finding)}</p><strong class="confidence">Evidence confidence · ${esc(agent.confidence)}</strong><small>Used: ${agent.sources.map(esc).join(' · ')}</small><small>Limit: ${esc(agent.limit)}</small></article>`).join('')}</div></section>`:''}${s.preview?`<section class="preview" aria-labelledby="preview-title"><span class="eyebrow">EXACT CHANGE · ${s.writes?'SAMPLE APPLIED':'PREVIEW ONLY'}</span><h2 id="preview-title">One license. Same buyer. Same SKU.</h2><div class="diff"><div><span>BEFORE</span><strong>${esc(s.preview.before)}</strong><small>${esc(s.preview.account)} · ${esc(s.preview.sku)}</small></div><div><span>${s.writes?'AFTER · SAMPLE RECORD':'AFTER · PROPOSED'}</span><strong>${esc(s.preview.after)}</strong><small>No refund, account transfer, or second license</small></div></div><p>${s.approval?'Sample merchant approval recorded for this exact assignment.':'The preview changes nothing. Merchant approval is required before a connected provider could make a change.'}</p></section>`:''}${s.proof?`<section class="proof" aria-labelledby="proof-title"><span class="eyebrow">OUTCOME CHECK</span><h2 id="proof-title">${complete?'Sample activation checked':'Activation could not be confirmed'}</h2><p>Payment match: ${s.proof.payment?'passed':'failed'} · Assignment: ${s.proof.assignment?'active':'missing'} · Activation: ${s.proof.activation?'accessible':'unverified'}. Buyer confirmation remains separate.</p></section>`:''}</div><aside class="action-card" aria-labelledby="action-title"><span class="eyebrow">NEXT SAFE STEP</span><h2 id="action-title" tabindex="-1">${s.phase==='paid'?'Begin with the records.':s.phase==='reviewed'?'Preview the smallest correction.':s.phase==='previewed'?'Approve this exact preview.':s.phase==='approved'?'Record one sample assignment.':s.phase==='applied'?'Prove activation separately.':s.phase==='verified'?'The sample story is complete.':'Hold the case.'}</h2><p>${s.phase==='paid'?'The sample purchase exists; no assignment has been made.':s.phase==='reviewed'?'The scripted specialists support a preview, not an automatic grant.':s.phase==='previewed'?'Approval is scoped to this buyer, order, and SKU.':s.phase==='approved'?'This click changes only the browser’s fictional sample.':s.phase==='applied'?'A write alone is not a verified outcome.':s.phase==='verified'?'A connected license provider and real buyer-access check are still needed for live support.':'The fictional evidence does not support a safe assignment.'}</p><button type="button" class="primary" id="advance" ${s.phase==='held'||s.phase==='unverified'?'disabled':''}>${esc(nextAction(s))}</button>${error?`<p class="error" role="alert">${esc(error)}</p>`:''}<div class="boundary"><strong>Integration boundary</strong><p>The connected app currently supports the reference course. Software licenses need a provider connector to read assignment state, apply one approved change, and test activation.</p></div><details><summary>Recorded sample activity</summary><ol>${s.events.map(event=>`<li>${esc(event)}</li>`).join('')}</ol></details></aside></div></div>`;
 root.querySelector('#advance')?.addEventListener('click',()=>{if(state.phase==='verified'){state=licenseSample();error='';render();return;}try{state=advanceLicenseSample(state);error='';}catch(cause){error=cause.message;}render();root.querySelector('#action-title')?.focus?.({preventScroll:true});});
}
render();
